// Async server component that fetches user data and displays name and email.
// Follows the existing server component data-fetching pattern used in page.tsx.
interface User {
  name: string
  email: string
}

async function getUser(): Promise<User> {
  try {
    const res = await fetch('/api/users/profile')
    return res.json()
  } catch {
    // Return mock data for build time
    return { name: 'Sample User', email: 'sample@example.com' }
  }
}

export default async function UserProfile() {
  const user = await getUser()

  return (
    <div>
      <h2>User Profile</h2>
      <p>Name: {user.name}</p>
      <p>Email: {user.email}</p>
    </div>
  )
}

